/*
 * Bootloader entry point for NUCLEO-F439ZI (STM32F439ZIT6).
 *
 * - System clock: 180 MHz from the ST-LINK 8 MHz MCO (HSE bypass) via PLL, overdrive on
 * - USART3 (PD8 TX / PD9 RX, wired to the ST-LINK virtual COM port), 115200 8N1
 * - LD2 (blue, PB7) is on while the bootloader runs; it goes off when the
 *   application takes over (HAL_DeInit resets the GPIO block)
 *
 * Replace the main.c generated by STM32CubeIDE with this file. The startup
 * file, linker script, stm32f4xx_hal_conf.h and stm32f4xx_it.c
 * (SysTick_Handler -> HAL_IncTick) still come from the Cube project.
 */

#include "stm32f4xx_hal.h"
#include "bootloader.h"

#define LED_BLUE_PORT   GPIOB
#define LED_BLUE_PIN    GPIO_PIN_7
#define LED_RED_PORT    GPIOB
#define LED_RED_PIN     GPIO_PIN_14

UART_HandleTypeDef huart3;

void Error_Handler(void);
static void SystemClock_Config(void);
static void LEDs_Init(void);
static void USART3_Init(void);

int main(void)
{
    HAL_Init();
    SystemClock_Config();
    LEDs_Init();
    USART3_Init();

    HAL_GPIO_WritePin(LED_BLUE_PORT, LED_BLUE_PIN, GPIO_PIN_SET);   /* bootloader active */

    bl_run(&huart3);     /* never returns: jumps to the app or serves updates */

    for (;;) { }
}

static void SystemClock_Config(void)
{
    RCC_OscInitTypeDef osc = {0};
    RCC_ClkInitTypeDef clk = {0};

    __HAL_RCC_PWR_CLK_ENABLE();
    __HAL_PWR_VOLTAGESCALING_CONFIG(PWR_REGULATOR_VOLTAGE_SCALE1);

    /* 8 MHz / 4 = 2 MHz, x180 = 360 MHz VCO, /2 = 180 MHz SYSCLK */
    osc.OscillatorType = RCC_OSCILLATORTYPE_HSE;
    osc.HSEState       = RCC_HSE_BYPASS;
    osc.PLL.PLLState   = RCC_PLL_ON;
    osc.PLL.PLLSource  = RCC_PLLSOURCE_HSE;
    osc.PLL.PLLM       = 4;
    osc.PLL.PLLN       = 180;
    osc.PLL.PLLP       = RCC_PLLP_DIV2;
    osc.PLL.PLLQ       = 8;
    if (HAL_RCC_OscConfig(&osc) != HAL_OK) Error_Handler();

    if (HAL_PWREx_EnableOverDrive() != HAL_OK) Error_Handler();

    clk.ClockType      = RCC_CLOCKTYPE_HCLK | RCC_CLOCKTYPE_SYSCLK |
                         RCC_CLOCKTYPE_PCLK1 | RCC_CLOCKTYPE_PCLK2;
    clk.SYSCLKSource   = RCC_SYSCLKSOURCE_PLLCLK;
    clk.AHBCLKDivider  = RCC_SYSCLK_DIV1;       /* HCLK  180 MHz */
    clk.APB1CLKDivider = RCC_HCLK_DIV4;         /* PCLK1  45 MHz */
    clk.APB2CLKDivider = RCC_HCLK_DIV2;         /* PCLK2  90 MHz */
    if (HAL_RCC_ClockConfig(&clk, FLASH_LATENCY_5) != HAL_OK) Error_Handler();
}

static void LEDs_Init(void)
{
    GPIO_InitTypeDef g = {0};

    __HAL_RCC_GPIOB_CLK_ENABLE();
    g.Pin   = LED_BLUE_PIN | LED_RED_PIN;
    g.Mode  = GPIO_MODE_OUTPUT_PP;
    g.Pull  = GPIO_NOPULL;
    g.Speed = GPIO_SPEED_FREQ_LOW;
    HAL_GPIO_Init(GPIOB, &g);
    HAL_GPIO_WritePin(GPIOB, LED_BLUE_PIN | LED_RED_PIN, GPIO_PIN_RESET);
}

/* Clocks and pins are set up here (not in HAL_UART_MspInit) so the file
 * works on its own and cannot clash with a Cube-generated MSP file. */
static void USART3_Init(void)
{
    GPIO_InitTypeDef g = {0};

    __HAL_RCC_GPIOD_CLK_ENABLE();
    __HAL_RCC_USART3_CLK_ENABLE();

    g.Pin       = GPIO_PIN_8 | GPIO_PIN_9;
    g.Mode      = GPIO_MODE_AF_PP;
    g.Pull      = GPIO_NOPULL;
    g.Speed     = GPIO_SPEED_FREQ_VERY_HIGH;
    g.Alternate = GPIO_AF7_USART3;
    HAL_GPIO_Init(GPIOD, &g);

    huart3.Instance          = USART3;
    huart3.Init.BaudRate     = 115200;
    huart3.Init.WordLength   = UART_WORDLENGTH_8B;
    huart3.Init.StopBits     = UART_STOPBITS_1;
    huart3.Init.Parity       = UART_PARITY_NONE;
    huart3.Init.Mode         = UART_MODE_TX_RX;
    huart3.Init.HwFlowCtl    = UART_HWCONTROL_NONE;
    huart3.Init.OverSampling = UART_OVERSAMPLING_16;
    if (HAL_UART_Init(&huart3) != HAL_OK) Error_Handler();
}

void Error_Handler(void)
{
    __disable_irq();
    HAL_GPIO_WritePin(LED_RED_PORT, LED_RED_PIN, GPIO_PIN_SET);   /* LD3 red = fatal error */
    for (;;) { }
}
